typedef long long ll;
ll f(ll n){if(n<0)return 0;ll r=n%4;return r==0?n:r==1?1:r==2?n+1:0;}
ll X(ll l,ll r){return f(r)^f(l-1);}
ll solve(ll l,ll r,int i,ll k){
  ll m=1LL<<i, ans=X(l,r);
  if(r<k) return ans;
  ll lo = l<=k?0:(l-k+m-1)/m, hi=(r-k)/m;
  if(lo>hi) return ans;
  ll ex=X(lo,hi)<<i; if((hi-lo+1)&1) ex|=k;
  return ans^ex;
}

