vector<int> zf(const string&s){int n=s.size();vector<int>z(n);z[0]=n;
 for(int i=1,l=0,r=0;i<n;i++){if(i<r)z[i]=min(r-i,z[i-l]);
  while(i+z[i]<n&&s[z[i]]==s[i+z[i]])z[i]++; if(i+z[i]>r)l=i,r=i+z[i];}return z;}
int solve(const string&s,int k){int n=s.size();auto z=zf(s);
 auto ok=[&](int L){if(L==0)return true;int c=0;for(int i=0;i<n;){if(z[i]>=L){c++;i+=L;}else i++;}return c>=k;};
 int lo=0,hi=n/k;while(lo<hi){int m=(lo+hi+1)/2;if(ok(m))lo=m;else hi=m-1;}return lo;}

