  for(int a=0;a<3;a++)for(int b=0;b<3;b++){long long v=0;
   for(int c=0;c<3;c++)for(int d=0;d<3;d++) if(ok(c,d)) v=(v+(long long)dp[l][m][a][c]*dp[m+1][r][d][b])%M;
