 vector<vector<pair<int,int>>>g(n);for(int i=0;i<n-1;i++){int u,v,w;scanf("%d %d %d",&u,&v,&w);u--;v--;g[u].push_back({v,w});g[v].push_back({u,w});}
 vector<int>order,par(n,-1),pw(n,0);order.reserve(n);vector<int>st={0};par[0]=n;
 while(!st.empty()){int v=st.back();st.pop_back();order.push_back(v);
  for(auto[u,w]:g[v])if(par[u]==-1){par[u]=v;pw[u]=w;st.push_back(u);}}
 // d0[v]: best in subtree, v uses <=k-1 child edges; d1[v]: <=k
 vector<ll>d0(n,0),d1(n,0);vector<vector<ll>>gain(n);
 for(int i=n-1;i>=0;i--){int v=order[i];
  sort(gain[v].rbegin(),gain[v].rend());ll s=0,sk1=0;int cnt=0;
  for(ll x:gain[v]){if(x<=0||cnt==k)break;if(cnt<k-1)sk1+=x;s+=x;cnt++;}
  ll base=d1[v];d0[v]=base+sk1;d1[v]=base+s;   // d1[v] accumulated sum of children's d1
  if(v){int p=par[v];d1[p]+=d1[v];gain[p].push_back(pw[v]+d0[v]-d1[v]);}
  vector<ll>().swap(gain[v]);}
 printf("%lld\n",d1[0]);}}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;typedef unsigned long long ull;
ull C[65][65];int K;
ull f(ull x){ // count y in [0,x] with popcount K
 ull r=0;int ones=0;for(int b=62;b>=0;b--)if(x>>b&1){if(K-ones>=0&&K-ones<=b)r+=C[b][K-ones];ones++;if(ones>K)break;}
 if(__builtin_popcountll(x)==K)r++;return r;}
int main(){for(int i=0;i<65;i++){C[i][0]=1;for(int j=1;j<=i;j++)C[i][j]=C[i-1][j-1]+C[i-1][j];}
 ull m;scanf("%llu %d",&m,&K);ull lo=1,hi=1000000000000000000ULL;
 while(lo<hi){ull mid=lo+(hi-lo)/2;if(f(2*mid)-f(mid)>=m)hi=mid;else lo=mid+1;}
 printf("%llu\n",lo);}
